16: /**
17:  * Compiles options into a numbered WhatsApp text menu fallback.
18:  * Formats cleanly with bold numbers and optional descriptions.
19:  */
20: export function buildTextMenu(
21:   header: string | undefined,
22:   bodyText: string,
23:   options: Array<{ id: string; title: string; description?: string }>,
24:   footer: string | undefined,
25: ): string {
26:   const lines: string[] = [];
27:   if (header && header.trim()) lines.push(`*${header.trim()}*\n`);
28:   if (bodyText && bodyText.trim()) lines.push(bodyText.trim());
29:   lines.push("");
30:   options.forEach((opt, idx) => {
31:     const desc = opt.description && opt.description.trim() ? ` - _${opt.description.trim()}_` : "";
32:     lines.push(`*${idx + 1}.* ${opt.title.trim()}${desc}`);
33:   });
34:   lines.push("");
35:   if (footer && footer.trim()) {
36:     lines.push(`_${footer.trim()}_`);
37:   } else {
38:     lines.push("_Reply with the number of your choice._");
39:   }
40:   return lines.join("\n");
41: }
