45:  */
46: export async function sendPresenceUpdate(
47:   apiKey: string,
48:   toPhone: string,
49:   type: "composing" | "recording" | "available" | "unavailable" = "composing",
50:   fetchImpl: typeof fetch = fetch,
51: ): Promise<void> {
52:   const PRESENCE_API = `${process.env.WASENDER_BASE_URL ?? "https://www.wasenderapi.com/api"}/send-presence-update`;
53:   await fetchImpl(PRESENCE_API, {
54:     method: "POST",
55:     headers: {
56:       Authorization: `Bearer ${apiKey}`,
57:       "Content-Type": "application/json",
58:     },
59:     body: JSON.stringify({ jid: toPhone, type }),
60:   }).catch(() => {});
61: }
