63: export function makeWasenderTransport(
64:   db?: BetterSqlite3.Database,
65:   storage: StorageProvider = createStorageFromEnv(),
66:   fetchImpl: typeof fetch = fetch,
67: ): (input: SendMessageInput & { apiKey: string }) => Promise<{ providerMessageId: string }> {
68:   return async (input) => {
69:     let payload: Record<string, unknown> = { to: input.toPhone };
70: 
71:     if (input.kind === "media") {
72:       let publicUrl = input.mediaUrl;
73:       let mime = input.mimeType?.toLowerCase();
74:       let fileName = input.filename;
75: 
76:       if (input.mediaId && db) {
77:         const asset = db
78:           .prepare("SELECT filename, mime_type, r2_key FROM media_assets WHERE id = ?")
79:           .get(input.mediaId) as { filename: string; mime_type: string; r2_key: string } | undefined;
80: 
81:         if (asset) {
82:           publicUrl = storage.getPublicUrl(asset.r2_key);
83:           mime = asset.mime_type.toLowerCase();
84:           fileName = asset.filename;
85:         }
86:       }
87: 
88:       if (publicUrl) {
89:         if (mime?.startsWith("image/") || publicUrl.match(/\.(jpg|jpeg|png|webp|gif)/i)) {
90:           payload.imageUrl = publicUrl;
91:           if (input.text) payload.text = input.text;
92:         } else if (mime?.startsWith("audio/") || publicUrl.match(/\.(mp3|ogg|wav|m4a)/i)) {
93:           payload.audioUrl = publicUrl;
94:         } else if (mime?.startsWith("video/") || publicUrl.match(/\.(mp4|mov|webm)/i)) {
95:           payload.videoUrl = publicUrl;
96:           if (input.text) payload.text = input.text;
97:         } else {
98:           payload.documentUrl = publicUrl;
99:           payload.fileName = fileName || "attachment.pdf";
100:           if (input.text) payload.text = input.text;
101:         }
102:       } else {
103:         if (input.text) payload.text = input.text;
104:       }
105:     } else {
106:       payload.text = input.text ?? "";
107:     }
108: 
109:     const res = await fetchImpl(WASENDER_API, {
110:       method: "POST",
111:       headers: {
112:         Authorization: `Bearer ${input.apiKey}`,
113:         "Content-Type": "application/json",
114:       },
115:       body: JSON.stringify(payload),
116:     });
117: 
118:     let resText = "";
119:     let body: any = {};
120:     if (typeof res.text === "function") {
121:       resText = await res.text().catch(() => "");
122:       try {
123:         body = JSON.parse(resText);
124:       } catch {
125:         body = { raw: resText };
126:       }
127:     } else if (typeof res.json === "function") {
128:       body = await res.json().catch(() => ({}));
129:     }
130: 
131:     if (!res.ok) {
132:       throw { status: res.status, body, rawText: resText, payload };
133:     }
134: 
135:     const providerMessageId =
136:       body.data?.key?.id ?? body.data?.message_id ?? body.data?.msgId ?? body.data?.id ?? `unconfirmed-${Date.now()}`;
137:     return { providerMessageId: String(providerMessageId), status: res.status, rawPayload: payload, rawResponse: body };
138:   };
139: }
